shipped_keybinds:
// Create new workspace through the existing Session Manager. This is
// intentionally a plugin focus, never a direct NewTab shortcut.
bind "Super n" {
    LaunchOrFocusPlugin "session-manager" {
        floating true
        move_to_focused_tab true
    };
}
// Quick cmd uses the active compact-bar's existing click path. Keep
// this in shared so the host's Cmd+Shift+. CSI-u event works in LOCK
// too; the bar itself selects only its active tab instance.
bind "Super Shift ." {
    MessagePlugin "compact-bar" {
        name "vc_quick_cmd"
    };
}
